from __future__ import annotations

import numpy as np
from sklearn.linear_model import LinearRegression
from sklearn.ensemble import RandomForestRegressor


class DragonNet:
    def __init__(self, neurons_per_layer=200, val_split=0.3, targeted_reg=True, propensity_model=None):
        # Use RandomForestRegressor instead of LinearRegression for non-linear relationships
        self.model_treat = RandomForestRegressor(n_estimators=100, max_depth=10, random_state=42, min_samples_leaf=5)
        self.model_control = RandomForestRegressor(n_estimators=100, max_depth=10, random_state=42, min_samples_leaf=5)
        self.propensity_model = propensity_model if propensity_model is not None else None
        self.fitted = False

    def fit(self, X, treatment, y):
        X = np.asarray(X)
        treatment = np.asarray(treatment).reshape(-1)
        y = np.asarray(y).reshape(-1)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        # Split by treatment
        idx_treat = treatment == 1
        idx_control = treatment == 0
        if np.any(idx_treat):
            self.model_treat.fit(X[idx_treat], y[idx_treat])
        else:
            self.model_treat.fit(X, y)
        if np.any(idx_control):
            self.model_control.fit(X[idx_control], y[idx_control])
        else:
            self.model_control.fit(X, y)
        self.fitted = True
        return self

    def predict_tau(self, X):
        X = np.asarray(X)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        if not self.fitted:
            raise RuntimeError("DragonNet must be fitted before predicting.")
        treat = self.model_treat.predict(X)
        control = self.model_control.predict(X)
        return (treat - control).reshape(-1, 1)

from __future__ import annotations

import numpy as np


def normalize(a):
    a = np.asarray(a, dtype=float)
    total = a.sum()
    if total == 0:
        return np.ones_like(a) / max(len(a), 1)
    return a / total
